import {
  computeKdjSeries,
  computeKdjObservation,
  IndicatorInputError,
  IndicatorValueError,
} from './index';

/**
 * Independent reference recurrence for the classic SMA(X, N, M)-smoothed KDJ
 * (plain JS, written directly from the formula — never generated by the production code).
 */
function classicKdjOracle(
  high: readonly number[],
  low: readonly number[],
  close: readonly number[],
  period: number,
  kSmoothing: number,
  dSmoothing: number,
): { begIndex: number; K: number[]; D: number[]; J: number[] } {
  const rsv: number[] = [];
  for (let t = period - 1; t < close.length; t += 1) {
    let hh = Number.NEGATIVE_INFINITY;
    let ll = Number.POSITIVE_INFINITY;
    for (let j = t - period + 1; j <= t; j += 1) {
      hh = Math.max(hh, high[j]);
      ll = Math.min(ll, low[j]);
    }
    const denom = hh - ll;
    rsv.push(denom === 0 ? 50 : ((close[t] - ll) / denom) * 100);
  }
  const ewma = (input: number[], alpha: number): number[] => {
    const out = [input[0]];
    for (let i = 1; i < input.length; i += 1) {
      out.push(out[i - 1] + alpha * (input[i] - out[i - 1]));
    }
    return out;
  };
  const kFull = ewma(rsv, 1 / kSmoothing);
  const dFull = ewma(kFull, 1 / dSmoothing);
  const drop = kSmoothing + dSmoothing - 2;
  const K = kFull.slice(drop);
  const D = dFull.slice(drop);
  const J = K.map((k, i) => 3 * k - 2 * D[i]);
  return { begIndex: close.length - K.length, K, D, J };
}

describe('computeKdjSeries', () => {
  const close = Array.from(
    { length: 80 },
    (_, index) => 100 + Math.sin(index / 3) * 5 + index * 0.7,
  );
  const high = close.map((value, index) => value + 2 + (index % 4) * 0.1);
  const low = close.map((value, index) => value - 2 - (index % 3) * 0.1);

  it('reproduces the classic (14,3,3) recurrence output exactly (golden + independent oracle)', () => {
    const result = computeKdjSeries(high, low, close, {
      period: 14,
      kSmoothing: 3,
      dSmoothing: 3,
    });
    const oracle = classicKdjOracle(high, low, close, 14, 3, 3);

    expect(result.begIndex).toBe(17);
    expect(result.K).toHaveLength(63);
    expect(result.D).toHaveLength(63);
    expect(result.J).toHaveLength(63);
    expect(result.K[0]).toBeCloseTo(57.601815, 6);
    expect(result.D[0]).toBeCloseTo(51.126565, 6);
    expect(result.J[0]).toBeCloseTo(70.552316, 6);
    expect(result.J[0]).toBeCloseTo(3 * result.K[0] - 2 * result.D[0], 10);
    result.K.forEach((value, index) =>
      expect(value).toBeCloseTo(oracle.K[index], 10),
    );
    result.D.forEach((value, index) =>
      expect(value).toBeCloseTo(oracle.D[index], 10),
    );
  });

  it('uses the catalog default (9,3,3) with classic SMA(X,3,1) smoothing', () => {
    const result = computeKdjSeries(high, low, close);
    const oracle = classicKdjOracle(high, low, close, 9, 3, 3);

    expect(result.begIndex).toBe(12);
    expect(result.K).toHaveLength(68);
    expect(result.K[0]).toBeCloseTo(41.904921, 6);
    expect(result.D[0]).toBeCloseTo(56.713644, 6);
    expect(result.J[0]).toBeCloseTo(12.287475, 6);
    expect(result.J[0]).toBeCloseTo(3 * result.K[0] - 2 * result.D[0], 10);
    result.K.forEach((value, index) =>
      expect(value).toBeCloseTo(oracle.K[index], 10),
    );
  });

  it('evaluates flat windows to K = D = J = 50 (zero-range RSV fallback)', () => {
    const flat = new Array<number>(20).fill(10);
    const result = computeKdjSeries(flat, flat, flat);

    expect(result.K.length).toBeGreaterThan(0);
    expect(result.K.every((value) => value === 50)).toBe(true);
    expect(result.D.every((value) => value === 50)).toBe(true);
    expect(result.J.every((value) => value === 50)).toBe(true);
  });

  it('is deterministic and does not mutate its inputs', () => {
    const h = [...high];
    const l = [...low];
    const c = [...close];

    const first = computeKdjSeries(high, low, close);
    const second = computeKdjSeries(high, low, close);

    expect(second).toEqual(first);
    expect(high).toEqual(h);
    expect(low).toEqual(l);
    expect(close).toEqual(c);
  });

  it('handles string-encoded numeric arrays gracefully (TypeORM decimal compatibility)', () => {
    const strHigh = high.map(String) as unknown as number[];
    const strLow = low.map(String) as unknown as number[];
    const strClose = close.map(String) as unknown as number[];

    const result = computeKdjSeries(strHigh, strLow, strClose);
    expect(result.K).toHaveLength(68);
    expect(result.K[0]).toBeCloseTo(41.904921, 6);
  });

  it('returns empty output for empty input', () => {
    const result = computeKdjSeries([], [], []);

    expect(result.begIndex).toBe(0);
    expect(result.K).toEqual([]);
    expect(result.D).toEqual([]);
    expect(result.J).toEqual([]);
  });
});

describe('computeKdjObservation', () => {
  const close = Array.from(
    { length: 13 },
    (_, index) => 100 + Math.sin(index / 2) * 3 + index * 0.5,
  );
  const high = close.map((value) => value + 1);
  const low = close.map((value) => value - 1);

  it('matches the trailing series value (invariant)', () => {
    const series = computeKdjSeries(high, low, close);
    const observation = computeKdjObservation(high, low, close, {
      windowSize: 13,
    });

    expect(observation.k).toBeCloseTo(series.K.at(-1) as number, 12);
    expect(observation.d).toBeCloseTo(series.D.at(-1) as number, 12);
    expect(observation.j).toBeCloseTo(series.J.at(-1) as number, 12);
  });

  it('enforces an exact window size', () => {
    expect(() =>
      computeKdjObservation(high, low, close.slice(0, 12), { windowSize: 13 }),
    ).toThrow(IndicatorInputError);
  });

  it('rejects unequal high/low/close lengths', () => {
    expect(() => computeKdjSeries(high, low, close.slice(0, 12))).toThrow(
      IndicatorInputError,
    );
  });

  it('throws IndicatorValueError when the trailing value is unavailable', () => {
    expect(() =>
      computeKdjObservation(
        high.slice(0, 3),
        low.slice(0, 3),
        close.slice(0, 3),
        { windowSize: 3 },
      ),
    ).toThrow(IndicatorValueError);
  });
});
